{"path":"events.html","content":"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Gatherings — {{BUSINESS_NAME}}</title>
<style>
:root{--bg:#0f1113;--card:#0b0c0d;--muted:#9aa0a6;--accent:#7dd3fc;--glass:rgba(255,255,255,0.03)}
*{box-sizing:border-box}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#e6eef3;background:linear-gradient(180deg,#071018 0%, #071016 60%), url('assets/img/pattern.svg');background-size:300px;min-height:100vh}
.header{display:flex;align-items:center;justify-content:space-between;padding:22px 28px}
.brand{font-weight:700;letter-spacing:0.4px;color:var(--accent)}
.nav{display:flex;gap:18px}
.nav a{color:var(--muted);text-decoration:none;padding:8px;border-radius:6px}
.nav a:hover{color:#fff;background:var(--glass)}
.hero{padding:40px 28px;display:grid;grid-template-columns:1fr 340px;gap:24px;align-items:start}
.hero .lead{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:28px;border-radius:12px}
.small{color:var(--muted);font-size:14px}
.card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px;margin-bottom:14px}
.next-event{border-left:3px solid var(--accent);padding-left:14px}
.calendar{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:12px;margin-top:12px}
.event-item{padding:12px;border-radius:10px;background:#071217;border:1px solid rgba(255,255,255,0.02)}
.meta{font-size:13px;color:var(--muted)}
.cta{display:inline-block;margin-top:12px;padding:10px 14px;background:var(--accent);color:#08202a;border-radius:8px;text-decoration:none;font-weight:600}
.disclaimer{font-size:13px;color:#d6dce2;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);padding:12px;border-radius:8px;margin-top:10px}
.footer{padding:28px;color:var(--muted);display:flex;justify-content:space-between;align-items:center}
@media(max-width:800px){.hero{grid-template-columns:1fr;}.nav{display:none}}
</style>
</head>
<body>
<header class="header">
<div class="brand">{{BUSINESS_NAME}}</div>
<nav class="nav">
<a href="events.html">Gatherings</a>
<a href="private-sessions.html">Privates</a>
<a href="pricing.html">Investment</a>
<a href="about.html">Story</a>
<a href="faq.html">Help</a>
<a href="book.html">{{PRIMARY_CTA_LABEL}}</a>
</nav>
</header>

<section class="hero">
<div class="lead">
<h1 style="margin:0 0 8px 0">Upcoming gatherings for focused unwinding</h1>
<p class="small">A series of guided sound experiences mixing bowls, subtle percussion and breath cues — crafted for quick recalibration after the day's friction.</p>

<div class="card next-event" id="nextEventCard">
<div class="meta">Next session</div>
<h2 id="nextEventTitle">Loading…</h2>
<div class="meta" id="nextEventWhen"></div>
<p id="nextEventBlurb" class="small" style="margin-top:8px"></p>
<a id="nextEventCTA" class="cta" href="{{PRIMARY_CTA_URL}}">Reserve a spot</a>
</div>

<div class="card">
<div class="meta">Quick calendar</div>
<div id="calendarList" class="calendar" aria-live="polite"></div>
</div>

<div class="card">
<div class="meta">Plan a group</div>
<p class="small">Private group sessions and studio rentals available. Tailored sequences for teams, retreats and small cohorts.</p>
<a class="cta" href="private-sessions.html">Inquire about privates</a>
</div>

</div>

<aside>
<div class="card">
<h3 style="margin:0 0 8px 0">Why come</h3>
<p class="small">Short-form sonic landscapes to lower the sympathetic tone and invite a clearer exhale. No prior practice required.</p>
</div>

<div class="card">
<h4 style="margin:0 0 8px 0">Contraindications</h4>
<p class="small">Sound sessions may not suit those with certain cardiovascular conditions, pregnancy without clearance, recent head injury, or implanted medical devices. Please consult your clinician and email <a href="mailto:{{EMAIL}}" style="color:var(--accent)">{{EMAIL}}</a> with questions.</p>
</div>

</aside>
</section>

<footer class="footer">
<div>{{CITY}}, {{STATE}} • <a href="contact.html" style="color:var(--muted);text-decoration:none">{{PHONE}}</a></div>
<div><a href="book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a></div>
</footer>

<script>
(function(){
const events = [
{title:'Dusk Breath Batch',date:'2026-03-05T18:30:00',blurb:'A steady 45-minute sound sequence for decompression.'},
{title:'Midday Clarity Session',date:'2026-02-20T12:15:00',blurb:'Short midday reset with bells and voice.'},
{title:'Weekend Deep Drift',date:'2026-03-14T10:00:00',blurb:'An extended group immersion for slow settling.'},
{title:'Lunar Evening',date:'2026-02-25T19:00:00',blurb:'Gentle tones and breath prompts to close the day.'}
];

function isoToLocal(d){const dt=new Date(d);return dt.toLocaleString(undefined,{weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}
function now(){return new Date()}
const upcoming = events.filter(e=>new Date(e.date)>now()).sort((a,b)=>new Date(a.date)-new Date(b.date));
const next = upcoming[0];
if(next){
document.getElementById('nextEventTitle').textContent = next.title;
document.getElementById('nextEventWhen').textContent = isoToLocal(next.date);
document.getElementById('nextEventBlurb').textContent = next.blurb;
document.getElementById('nextEventCTA').href = 'book.html?event='+encodeURIComponent(next.title);
} else {
document.getElementById('nextEventCard').innerHTML = '<div class="meta">No upcoming sessions</div><p class="small">No scheduled gatherings are available right now. Sign up to be notified when new dates are added.</p><a class="cta" href="contact.html">Contact us</a>'
}

const list = document.getElementById('calendarList');
events.sort((a,b)=>new Date(a.date)-new Date(b.date)).forEach(e=>{
const el = document.createElement('div');
el.className='event-item';
el.innerHTML = '<strong>'+e.title+'</strong><div class="meta">'+isoToLocal(e.date)+'</div><div class="small" style="margin-top:6px">'+e.blurb+'</div><a class="cta" style="margin-top:8px;display:inline-block" href="book.html?event='+encodeURIComponent(e.title)+'">Join</a>';
list.appendChild(el);
});

// lightweight local subscribe (no backend)
window.subscribeToNotify = function(){
alert('Thanks — we will reach out with new dates. Email: {{EMAIL}}');
}
})();
</script>
</body>
</html>"} 
{"path":"private-sessions.html","content":"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Privates — {{BUSINESS_NAME}}</title>
<style>
:root{--bg:#071018;--card:#071217;--accent:#a7f3d0;--muted:#9fb0b6;--glass:rgba(255,255,255,0.03)}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#e8f6f2;background:linear-gradient(180deg,#031014 0%,#061216 60%), url('assets/img/pattern.svg');background-size:400px}
.header{display:flex;justify-content:space-between;align-items:center;padding:20px 26px}
.brand{font-weight:700;color:var(--accent)}
.nav a{color:var(--muted);text-decoration:none;margin-left:16px}
.container{padding:28px}
.grid{display:grid;grid-template-columns:1fr 320px;gap:18px}
.card{background:rgba(255,255,255,0.02);padding:18px;border-radius:12px}
.selector{display:flex;gap:10px;flex-wrap:wrap;margin-top:10px}
.btn{padding:10px 12px;border-radius:10px;background:#062122;color:var(--muted);border:1px solid rgba(255,255,255,0.02);cursor:pointer}
.btn.active{background:linear-gradient(90deg,var(--accent),#5eead4);color:#062a28;font-weight:700}
.recommend{margin-top:12px}
.cta{display:inline-block;padding:10px 14px;background:var(--accent);color:#032019;border-radius:9px;text-decoration:none;font-weight:700;margin-top:10px}
.small{color:var(--muted);font-size:14px}
.disclaimer{font-size:13px;color:#cfe9e0;margin-top:12px}
@media(max-width:800px){.grid{grid-template-columns:1fr}}
</style>
</head>
<body>
<header class="header">
<div class="brand">{{BUSINESS_NAME}}</div>
<nav class="nav">
<a href="events.html">Gatherings</a>
<a href="private-sessions.html">Privates</a>
<a href="pricing.html">Value</a>
<a href="book.html">{{PRIMARY_CTA_LABEL}}</a>
</nav>
</header>

<main class="container">
<h1 style="margin:0 0 8px 0">Private sessions and tailored sequences</h1>
<p class="small">One-on-one and bespoke team sessions that scale from quick corporate resets to multi-hour bespoke sound design.</p>

<div class="grid" aria-live="polite">
<div class="card">
<h3 style="margin-top:0">Select how you feel</h3>
<div class="selector" id="moodSelector">
<button class="btn" data-key="tense">Tense</button>
<button class="btn" data-key="fatigued">Fatigued</button>
<button class="btn" data-key="wired">Wired</button>
<button class="btn" data-key="curious">Curious</button>
</div>

<div class="recommend card" id="recommendation">
<h4 id="recTitle">A considered approach</h4>
<p id="recMethod" class="small">Choose a state above to see a recommended private approach.</p>
<div id="recDetails" class="small" style="margin-top:8px"></div>
<a id="recCTA" class="cta" href="book.html">{{PRIMARY_CTA_LABEL}}</a>
</div>

<div class="card" style="margin-top:12px">
<h4 style="margin:0 0 8px 0">Contraindications & safety</h4>
<p class="small">Privates include some sustained tones and low-frequency elements. If you have health concerns (cardiac conditions, pregnancy without clearance, epilepsy, cochlear implants), consult your care provider. Email <a href="mailto:{{EMAIL}}" style="color:var(--accent)">{{EMAIL}}</a> for pre-session questions.</p>
</div>

</div>

<aside>
<div class="card">
<h4 style="margin:0 0 8px 0">Session formats</h4>
<ul style="padding-left:18px;color:var(--muted)">
<li>Short Reset — 30 min, guided</li>
<li>Individual Deep — 60–90 min, bespoke</li>
<li>Team Workshop — 90–180 min, interactive</li>
</ul>
</div>

<div class="card" style="margin-top:12px">
<h4 style="margin:0 0 8px 0">Contact</h4>
<p class="small">Call <a href="tel:{{PHONE}}" style="color:var(--accent)">{{PHONE}}</a> or <a href="mailto:{{EMAIL}}" style="color:var(--accent)">{{EMAIL}}</a></p>
</div>
</aside>

</main>

<script>
(function(){
const map = {
tense:{title:'Slow-release sequence',method:'Long, settling bowls with heartbeat pacing',details:'60 minutes. Emphasis on grounding, weighted tones, and paced breath work.',ctaLabel:'Book a grounding session',ctaUrl:'book.html?type=tense'},
fatigued:{title:'Refresh & Reset',method:'Brighter overtones, short breath cues and gentle movement',details:'30–45 minutes. Designed to restore alertness without overstimulation.',ctaLabel:'Reserve a refresher',ctaUrl:'book.html?type=fatigued'},
wired:{title:'Rhythm and Release',method:'Interleaved percussion and sustained drones to recalibrate energy',details:'45–75 minutes. For high activation needing structured descent.',ctaLabel:'Schedule a recalibration',ctaUrl:'book.html?type=wired'},
curious:{title:'Exploratory sound design',method:'Tailored sonic experiments and listening prompts',details:'Flexible duration. For those wanting playful inquiry into sound.',ctaLabel:'Start a discovery session',ctaUrl:'book.html?type=curious'}
};

const buttons = document.querySelectorAll('#moodSelector .btn');
function clearActive(){buttons.forEach(b=>b.classList.remove('active'))}
function apply(key,btn){
clearActive();btn.classList.add('active');
const d=map[key];
document.getElementById('recTitle').textContent = d.title;
document.getElementById('recMethod').textContent = d.method;
document.getElementById('recDetails').textContent = d.details;
const cta = document.getElementById('recCTA');
cta.textContent = d.ctaLabel;
cta.href = d.ctaUrl;
}
buttons.forEach(b=>{
b.addEventListener('click',function(){apply(this.dataset.key,this)});
});

// set default
apply('fatigued',document.querySelector('[data-key="fatigued"]'));
})();
</script>

</body>
</html>"} 
{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Investment — Pricing — {{BUSINESS_NAME}}</title>
<style>
:root{--bg:#071016;--card:#08121a;--accent:#ffd6a5;--muted:#9fb3b9}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#eef8f6;background:linear-gradient(180deg,#021214 0%,#06131a 60%), url('assets/img/pattern.svg');background-size:360px}
.header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px}
.brand{font-weight:700;color:var(--accent)}
.nav a{color:var(--muted);text-decoration:none;margin-left:14px}
.container{padding:28px}
.toggle{display:flex;align-items:center;gap:12px;background:rgba(255,255,255,0.02);padding:10px;border-radius:999px;width:max-content}
.switch{width:44px;height:24px;border-radius:999px;background:#0b2a2c;position:relative;cursor:pointer}
.knob{width:20px;height:20px;border-radius:50%;background:var(--accent);position:absolute;top:2px;left:2px;transition:left .28s cubic-bezier(.2,.9,.2,1)}
.pricing-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin-top:18px}
.plan{background:rgba(255,255,255,0.02);padding:16px;border-radius:12px}
.price{font-size:28px;font-weight:800;color:var(--accent)}
.small{color:var(--muted)}
.footnote{font-size:13px;color:var(--muted);margin-top:12px}
.cta{display:inline-block;padding:9px 12px;background:var(--accent);color:#041818;border-radius:8px;text-decoration:none;font-weight:700;margin-top:10px}
.disclaimer{font-size:13px;color:#dceeea;margin-top:12px}
@media(max-width:800px){.header{padding:14px}}
</style>
</head>
<body>
<header class="header">
<div class="brand">{{BUSINESS_NAME}}</div>
<nav class="nav">
<a href="pricing.html">Value</a>
<a href="events.html">Gatherings</a>
<a href="private-sessions.html">Sessions</a>
<a href="faq.html">FAQs</a>
<a href="book.html">{{PRIMARY_CTA_LABEL}}</a>
</nav>
</header>

<main class="container">
<h1 style="margin:0 0 8px 0">Investment options</h1>
<p class="small">Transparent options that frame sound work as either a recurring practice or a block purchase. Toggle to compare.</p>

<div style="margin-top:18px" aria-label="Pricing comparator">
<div class="toggle" id="pricingToggle" role="switch" aria-checked="false" tabindex="0">
<div style="font-size:13px;color:var(--muted)">Monthly</div>
<div class="switch" id="switch">
<div class="knob" id="knob"></div>
</div>
<div style="font-size:13px;color:var(--muted)">Package</div>
</div>
</div>

<div class="pricing-grid" id="plans">
<div class="plan" data-month="35" data-package="180">
<h3 style="margin-top:0">Entry Flow</h3>
<div class="price" data-target>—</div>
<div class="small">Ideal for those starting a brief weekly practice. Includes recordings.</div>
<a class="cta" href="book.html?plan=entry" id="cta-entry">Choose</a>
</div>

<div class="plan" data-month="65" data-package="340">
<h3 style="margin-top:0">Core Sequence</h3>
<div class="price" data-target>—</div>
<div class="small">Our most popular rhythm: consistent work over a month for steady results.</div>
<a class="cta" href="book.html?plan=core" id="cta-core">Choose</a>
</div>

<div class="plan" data-month="120" data-package="640">
<h3 style="margin-top:0">Bespoke Block</h3>
<div class="price" data-target>—</div>
<div class="small">A package of prioritized sessions, custom scheduling and a prep call.</div>
<a class="cta" href="book.html?plan=bespoke" id="cta-bespoke">Choose</a>
</div>
</div>

<div class="footnote">Package prices reflect pre-paid bundles; monthly reflects typical per-session cost when billed across a cycle.</div>

<div class="disclaimer">
<h4 style="margin:6px 0">Health & safety</h4>
<p class="small">If you have a pacemaker, inner ear implants, are pregnant without medical clearance, or have a recent concussion, please consult your provider before attending. Reach out to <a href="mailto:{{EMAIL}}" style="color:var(--accent)">{{EMAIL}}</a> with concerns.</p>
</div>

</main>

<script>
(function(){
const toggle = document.getElementById('pricingToggle');
const switchEl = document.getElementById('switch');
const knob = document.getElementById('knob');
let packageMode = false;
function animateNumber(el,from,to,duration=700){
let start = null;
const diff = to - from;
function step(ts){
if(!start) start = ts;
const p = Math.min((ts-start)/duration,1);
const val = Math.round(from + diff * (1 - Math.pow(1-p,3)));
el.textContent = '$' + val;
if(p<1) requestAnimationFrame(step);
}
requestAnimationFrame(step);
}
function refreshPrices(){
document.querySelectorAll('.plan').forEach(plan=>{
const month = parseInt(plan.dataset.month,10);
const pack = parseInt(plan.dataset.package,10);
const target = plan.querySelector('[data-target]');
const from = parseInt(target.textContent.replace(/[^0-9]/g,''))||0;
const to = packageMode ? pack : month;
animateNumber(target,from,to);
});
}
toggle.addEventListener('click',function(){
packageMode = !packageMode;
knob.style.left = packageMode ? '22px' : '2px';
toggle.setAttribute('aria-checked', packageMode);
refreshPrices();
});
// keyboard support
toggle.addEventListener('keydown',function(e){ if(e.key==='Enter' || e.key===' ') { e.preventDefault(); toggle.click(); }});

// initial render
document.querySelectorAll('.plan').forEach((p,i)=>{
const el = p.querySelector('[data-target]');
el.textContent = '$' + p.dataset.month;
});
setTimeout(refreshPrices,300);

// CTA text morph: change phrasing depending on mode
function updateCTAs(){
document.querySelectorAll('.plan').forEach(p=>{
const id = p.querySelector('.cta').id;
const base = p.querySelector('h3').textContent;
const a = p.querySelector('.cta');
if(packageMode){
a.textContent = 'Buy package';
a.href = 'book.html?package='+encodeURIComponent(base.toLowerCase());
} else {
a.textContent = 'Subscribe';
a.href = 'book.html?monthly='+encodeURIComponent(base.toLowerCase());
}
});
}
toggle.addEventListener('click',updateCTAs);
updateCTAs();

})();
</script>

</body>
</html>"} 
